const navigationRows:FileSearchResult[]=[['projects','directory'],['projects/sub','directory'],['projects/empty','directory'],['projects/report.txt','file'],['projects/sub/deep.txt','file'],['root-public.txt','file'],['reports','directory']].map(([path,kind],index)=>({id:`${rootId}:${path}`,rootId,generation,path:path!,kind:kind as 'file'|'directory',size:index+1,modifiedMs:1792886400000}));
