 it('restores all-folder origin after browsing a result from another registered root',async()=>{const row={...navigationRows[0]!,id:`${otherId}:archive`,rootId:otherId,path:'archive'},api=navigationSearch([...navigationRows,row]),f=setup({search:api},[root,{...root,id:otherId,name:'Public archive'}]);await settled();await invoke(f.controller,'files:all');f.controller.session.setQuery(top(f.controller).view.viewId,'archive');f.controller.query(top(f.controller).view.viewId,'archive');await new Promise(resolve=>setTimeout(resolve,170));await invoke(f.controller,'files:browse',row.id);await new Promise(resolve=>setTimeout(resolve,20));expect(api).toHaveBeenLastCalledWith({query:'',rootId:otherId,directory:'archive'});await invoke(f.controller,'files:return-scope');await new Promise(resolve=>setTimeout(resolve,20));expect(api).toHaveBeenLastCalledWith({query:'archive'});expect(top(f.controller)).toMatchObject({query:'archive',selection:row.id});});
